export async function getWithRetry(endpoint: string, tries = 3): Promise<Response> {
	let wait = 200;
	for (let n = 0; n < tries; n++) {
		const response = await fetch(endpoint);
		if (response.ok) return response;
		await sleep(wait);
		wait *= 2;
	}
	throw new Error(`gave up on ${endpoint} after ${tries} attempts`);
}
